    List<Attribute> attrs = posAttrs(self, "Stmt.ExprStmt", pos.line, pos.column);
    XmlNode node = XmlNode("Stmt", attrs, makeList<XmlNode>());
    attach(self, node, "Expr", expr.node);
    return node;
