Str matchingOpenToken(Str closingToken) {
    if (closingToken == ">") {
        return "<";
    }
    if (closingToken == "}") {
        return "{";
    }
    if (closingToken == "]") {
        return "[";
    }
    if (closingToken == ")") {
        return "(";
    }
    return "";
}
