SkeletonType blockTypeForOpenToken(Str openingToken) {
    if (openingToken == "(") {
        return SkeletonType::Paren;
    }
    if (openingToken == "[") {
        return SkeletonType::Square;
    }
    if (openingToken == "{") {
        return SkeletonType::Block;
    }
    if (openingToken == "<") {
        return SkeletonType::Generics;
    }
    return SkeletonType::None;
}
